pragma solidity 0.8.17;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/Nabana.sol";

contract MockNabana {
    function mintWithPermit(address, uint256) external pure returns (bool) {
        return true;
    }
}

contract NabanaAuditTest is Test {
    NabanaDividendTracker public dividendTracker;
    MockNabana public mockNabana;
    address privateAccount = address(0x1000);

    function setUp() public {
        mockNabana = new MockNabana();
        dividendTracker = new NabanaDividendTracker(address(mockNabana));
    }

    function testExcludedAccountReaddedToInvestorsMap() public {
        // Exclude account from dividends
        dividendTracker.excludeFromDividends(privateAccount);
        assertTrue(dividendTracker.excludedFromDividends(privateAccount));

        // Initially remove account from investors map
        dividendTracker.setBalance(privateAccount, 0);
        (,,,,, uint256 initialInvestment,) = dividendTracker.getAccount(privateAccount);
        assertEq(initialInvestment, 0, "Account should start with zero balance");

        // Attempt to set balance above minimum
        uint8 result = dividendTracker.setBalance(privateAccount, 1); // Minimum is 1 wei
        assertEq(result, 2, "Result should be 'excluded account' (2)");

        // Check if excluded account was improperly added to investors map
        (,,,,, uint256 currentInvestment,) = dividendTracker.getAccount(privateAccount);
        assertGt(currentInvestment, 0, "Vulnerability: Excluded account added to investors map");
        assertEq(currentInvestment, 1, "Account balance should be set to 1 wei");
    }
}
